class Solution:
    def splitLoopedString(self, strs):
        best = lambda s: max(s, s[::-1])
        others = ''.join(best(s) for s in strs)
        ans = ''
        n = len(strs)
        for i, s in enumerate(strs):
            rest = others[:sum(len(x) for x in strs[:i])] + others[sum(len(x) for x in strs[:i]) + len(s):]
            for o in (s, s[::-1]):
                for j in range(len(o)):
                    cand = o[j:] + o[:j] + rest
                    if cand > ans:
                        ans = cand
        return ans

