class Solution {
public:
    string splitLoopedString(vector<string>& strs) {
        auto best = [](const string& s){ string r(s.rbegin(), s.rend()); return max(s, r); };
        string others;
        vector<string> bs;
        for (auto& s : strs) { bs.push_back(best(s)); others += bs.back(); }
        string ans;
        int n = strs.size();
        for (int i = 0; i < n; i++) {
            string rest = others.substr(0, others.size() - bs[i].size());
            for (string o : {strs[i], string(strs[i].rbegin(), strs[i].rend())}) {
                for (int j = 0; j < (int)o.size(); j++) {
                    string cand = o.substr(j) + o.substr(0, j) + rest;
                    ans = max(ans, cand);
                }
            }
        }
        return ans;
    }
};

