class Solution {
    public String splitLoopedString(String[] strs) {
        String[] bs = new String[strs.length];
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < strs.length; i++) {
            String r = new StringBuilder(strs[i]).reverse().toString();
            bs[i] = strs[i].compareTo(r) > 0 ? strs[i] : r;
            sb.append(bs[i]);
        }
        String others = sb.toString(), ans = "";
        for (int i = 0; i < strs.length; i++) {
            String rest = others.replace(bs[i], "");
            String rev = new StringBuilder(strs[i]).reverse().toString();
            for (String o : new String[]{strs[i], rev}) {
                for (int j = 0; j < o.length(); j++) {
                    String cand = o.substring(j) + o.substring(0, j) + rest;
                    if (cand.compareTo(ans) > 0) ans = cand;
                }
            }
        }
        return ans;
    }
}

