class Solution {
    public String splitLoopedString(String[] strs) {
        int n = strs.length;
        String[] bs = new String[n];
        char m = 0;
        for (int i = 0; i < n; i++) {
            String r = new StringBuilder(strs[i]).reverse().toString();
            bs[i] = strs[i].compareTo(r) > 0 ? strs[i] : r;
            m = (char) Math.max(m, bs[i].charAt(0));
        }
        String ans = "";
        for (int i = 0; i < n; i++) {
            if (bs[i].charAt(0) != m) continue;
            StringBuilder sb = new StringBuilder();
            for (int k = 0; k < n; k++) if (k != i) sb.append(bs[k]);
            String rest = sb.toString();
            for (int j = 0; j < bs[i].length(); j++) {
                String cand = bs[i].substring(j) + bs[i].substring(0, j) + rest;
                if (cand.compareTo(ans) > 0) ans = cand;
            }
        }
        return ans;
    }
}

