var splitLoopedString = function(strs) {
    const bs = strs.map(s => { const r = [...s].reverse().join(''); return s > r ? s : r; });
    const m = Math.max(...bs.map(b => b.charCodeAt(0)));
    let ans = '';
    for (let i = 0; i < bs.length; i++) {
        if (bs[i].charCodeAt(0) !== m) continue;
        const rest = bs.filter((_, k) => k !== i).join('');
        for (let j = 0; j < bs[i].length; j++) {
            const cand = bs[i].slice(j) + bs[i].slice(0, j) + rest;
            if (cand > ans) ans = cand;
        }
    }
    return ans;
};
